(function($){'use strict';var ShahiDashboard={init:function(){console.log('ShahiLegalFlowSuite Dashboard:Initializing...');this.initAnimatedCounters();this.initRefreshButton();this.initActivityFeed();this.initQuickActions();this.initCollapsibleSections();this.initOnboardingTrigger();this.initTooltips();console.log('ShahiLegalFlowSuite Dashboard:Initialized successfully');},initAnimatedCounters:function(){var $counters=$('.shahi-stat-number[data-value]');if($counters.length===0){return;}$counters.each(function(){var $counter=$(this);var targetValue=parseInt($counter.attr('data-value'))||0;var currentValue=0;var duration=2000;var steps=60;var increment=targetValue/steps;var stepDuration=duration/steps;var stepCount=0;if(isNaN(targetValue)){return;}$counter.text('0');var interval=setInterval(function(){stepCount++;currentValue=Math.min(Math.round(increment*stepCount),targetValue);$counter.text(currentValue.toLocaleString());if(stepCount>=steps||currentValue>=targetValue){clearInterval(interval);$counter.text(targetValue.toLocaleString());}},stepDuration);});},initRefreshButton:function(){var self=this;$('[data-action="refresh"]').on('click',function(e){e.preventDefault();self.refreshStats($(this));});},refreshStats:function($button){var self=this;$button.addClass('shahi-loading');$button.prop('disabled',true);setTimeout(function(){self.initAnimatedCounters();$button.removeClass('shahi-loading');$button.prop('disabled',false);if(typeof window.ShahiNotify!=='undefined'){window.ShahiNotify.success('Dashboard stats refreshed successfully!');}},1000);},initActivityFeed:function(){var $activityItems=$('.shahi-activity-item');$activityItems.each(function(index){$(this).css({opacity:0,transform:'translateX(-20px)'}).delay(index*50).animate({opacity:1},300,function(){$(this).css('transform','translateX(0)');});});},initQuickActions:function(){var $quickActions=$('.shahi-quick-action');$quickActions.on('mouseenter',function(){$(this).find('.shahi-action-icon').addClass('shahi-wobble');});$quickActions.on('mouseleave',function(){$(this).find('.shahi-action-icon').removeClass('shahi-wobble');});},initCollapsibleSections:function(){$('.shahi-card-header').on('dblclick',function(){var $cardBody=$(this).next('.shahi-card-body');$cardBody.slideToggle(300);$(this).toggleClass('shahi-collapsed');});},initOnboardingTrigger:function(){$('.shahi-trigger-onboarding').on('click',function(e){e.preventDefault();if(typeof window.ShahiOnboarding!=='undefined'){window.ShahiOnboarding.show();}else{console.warn('ShahiOnboarding module not loaded');if(confirm('This will reset the onboarding wizard. Continue?')){$.ajax({url:shahiDashboard.ajaxUrl,type:'POST',data:{action:'shahi_restart_onboarding',nonce:shahiDashboard.nonce},success:function(){window.location.reload();}});}}});},initTooltips:function(){if(typeof window.ShahiComponents!=='undefined'&&typeof window.ShahiComponents.initTooltips==='function'){window.ShahiComponents.initTooltips();}},formatNumber:function(num){return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');},calculateProgress:function(){var $checklistItems=$('.shahi-checklist-item');var totalItems=$checklistItems.length;var completedItems=$checklistItems.filter('.shahi-completed').length;if(totalItems===0){return 0;}return Math.round((completedItems/totalItems)*100);},updateProgressBar:function(){var progress=this.calculateProgress();var $progressBar=$('.shahi-getting-started-progress');if($progressBar.length){$progressBar.css('width',progress+'%');$progressBar.find('.shahi-progress-text').text(progress+'%');}}};$(document).ready(function(){if($('.shahi-dashboard-page').length>0){ShahiDashboard.init();}});window.ShahiDashboard=ShahiDashboard;})(jQuery);